package io.forgeloop.harness;
import java.util.*;
public final class FeatureRun { private final String featureId; private DeliveryState state=DeliveryState.RECEIVED; private final Map<String,Integer> repairs=new HashMap<>(); public FeatureRun(String featureId){this.featureId=featureId;} public DeliveryState state(){return state;} public String featureId(){return featureId;} public void plan(){transition(DeliveryState.RECEIVED,DeliveryState.PLANNED);} public void execute(){transition(DeliveryState.PLANNED,DeliveryState.EXECUTING);} public void verify(){transition(DeliveryState.EXECUTING,DeliveryState.VERIFYING);} public void record(VerificationResult result,int maxRepairs){if(state!=DeliveryState.VERIFYING)throw new IllegalStateException("Not verifying");if(result.passed())return;int attempts=repairs.merge(result.gate(),1,Integer::sum);state=attempts>maxRepairs?DeliveryState.BLOCKED:DeliveryState.REPAIRING;} public void repaired(){transition(DeliveryState.REPAIRING,DeliveryState.VERIFYING);} public void review(List<VerificationResult> results){if(state!=DeliveryState.VERIFYING||results.stream().anyMatch(r->!r.passed()))throw new IllegalStateException("All gates must pass before review");state=DeliveryState.REVIEWING;} public void ready(){transition(DeliveryState.REVIEWING,DeliveryState.READY_FOR_REVIEW);} private void transition(DeliveryState from,DeliveryState to){if(state!=from)throw new IllegalStateException("Expected "+from+" but was "+state);state=to;} }
